    @field_validator("frontend_origins")
    @classmethod
    def validate_origins(cls, value: str) -> str:
        parse_url = TypeAdapter(HttpUrl).validate_python
        origins = []
        for origin in value.split(","):
            origin = origin.strip()
            if not origin:
                continue
            if origin == "*":
                origins.append("*")
